import json, numpy as np, os, time
ROOT='/app/output/'
Q=[0,1,0,0]
WELLS=[[-.155+.022*i,.138,.026] for i in range(6)]+[[-.155+.022*i,.160,.026] for i in range(6)]+[[-.133+.022*i,.182,.026] for i in range(4)]
class Motion:
 def __init__(self):
  m=json.load(open(ROOT+'latest_meta.json')) if os.path.exists(ROOT+'latest_meta.json') else json.load(open('/app/runs/start/meta.json'))
  self.p=np.array(m['proprio']['now'][7:10]);self.rows=[]
 def move(self,p,speed=.15,hold=0):
  p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-self.p)/speed/.05)))
  self.rows.extend([list(a)+Q for a in np.linspace(self.p,p,n+1)[1:]])
  self.rows.extend([list(p)+Q]*int(round(hold/.05)));self.p=p
 def lift(self):self.move([*self.p[:2],.055],.08,.1)
 def dip(self,col):
  self.lift();w=WELLS[col];self.move([*w[:2],.065]);self.move(w,.06,.3);self.move([*w[:2],.065],.06,.1)
 def sweep(self,points,depth=.005,speed=.045):
  self.lift();self.move([*points[0],.055]);self.move([*points[0],.0202-depth],.035,.2)
  for p in points[1:]:self.move([*p,.0202-depth],speed)
  self.move([*points[-1],.0202-depth],speed,.15);self.lift()
 def park(self):self.lift();self.move([-.3,0,.17],.15,.3)
 def send(self,note,out=None,obs_cameras=None):
  c={'op':'exec','note':note,'batches':[{'poses':self.rows[i:i+180]} for i in range(0,len(self.rows),180)],'out':out,'obs_cameras':obs_cameras}
  json.dump(c,open(ROOT+note+'.json','w'))
  if os.path.exists(ROOT+'done.json'):os.remove(ROOT+'done.json')
  json.dump(c,open(ROOT+'command.tmp','w'));os.rename(ROOT+'command.tmp',ROOT+'command.json')
  print(len(self.rows),'control steps',len(c['batches']),'calls')
def uv(u,v):return [.0135925-v*.227185/1024,.1135925-u*.227185/1024]
if __name__=='__main__':
