#include <cmath>
#include <cstdio>
#include <vector>
#include <random>
#include <algorithm>
#include <fstream>
using namespace std;
const int N=256; float T[N*N*3],C[N*N*3],P[16*3];
mt19937 rng(541);float R(){return generate_canonical<float,24>(rng);}float normal(){static normal_distribution<float>d(0,1);return d(rng);}
struct S{float x,y,a,len,w,g;int c;};
float evaluate(S &s,bool apply=false){
 float dx=cos(s.a),dy=sin(s.a),h=s.len/2,r=s.w/2,feather=1.7;
 float x0=s.x-dx*h,y0=s.y-dy*h,x1=s.x+dx*h,y1=s.y+dy*h;
 int l=max(0,(int)floor(min(x0,x1)-r-feather)),rr=min(N-1,(int)ceil(max(x0,x1)+r+feather));
 int top=max(0,(int)floor(min(y0,y1)-r-feather)),bot=min(N-1,(int)ceil(max(y0,y1)+r+feather));
 double A=0,B[3]={0,0,0},D=0;
 for(int y=top;y<=bot;y++)for(int x=l;x<=rr;x++){
  float vx=x-s.x,vy=y-s.y,u=max(-h,min(h,vx*dx+vy*dy));
  float dist=hypot(vx-u*dx,vy-u*dy);float alpha=max(0.f,min(1.f,(r+feather-dist)/(2*feather)));alpha=alpha*alpha*(3-2*alpha);
  if(alpha<=0)continue;int k=(y*N+x)*3;
  if(apply){for(int j=0;j<3;j++)C[k+j]=C[k+j]*(1-alpha)+P[s.c*3+j]*alpha;continue;}
  float aa=alpha*alpha;A+=aa;
  for(int j=0;j<3;j++){float c=C[k+j],t=T[k+j];B[j]+=alpha*(t-c)+aa*c;D+=2*alpha*c*(t-c)+aa*c*c;}
 }
 if(apply)return 0;
 double best=-1e30;int col=0;
 for(int c=0;c<16;c++){double gain=-D;for(int j=0;j<3;j++){float p=P[c*3+j];gain+=2*p*B[j]-p*p*A;}if(gain>best){best=gain;col=c;}}
 s.c=col;s.g=best;return best;
}
int main(int argc,char**argv){
 FILE*f=fopen(argv[1],"rb");fread(T,4,N*N*3,f);fread(C,4,N*N*3,f);fread(P,4,48,f);fclose(f);
 int count=atoi(argv[3]);float maxw=atof(argv[4]),minw=atof(argv[5]);ofstream out(argv[2]);
 for(int iter=0;iter<count;iter++){
  vector<double> weights(N*N);double acc=0;
  for(int k=0;k<N*N;k++){double e=0;for(int j=0;j<3;j++)e+=pow(T[k*3+j]-C[k*3+j],2);weights[k]=acc+=e+2;}
  S best{};best.g=-1e30;
  vector<S> candidates;
  for(int k=0;k<900;k++){
   int pos=lower_bound(weights.begin(),weights.end(),R()*acc)-weights.begin();
   S s;s.x=pos%N;s.y=pos/N;s.a=R()*M_PI;s.w=minw+(maxw-minw)*pow(R(),.45);s.len=2+pow(R(),2)*100;
   if(k%3==0)s.a=(R()<.5?0:M_PI/2)+normal()*.15;
   evaluate(s);candidates.push_back(s);
  }
  sort(candidates.begin(),candidates.end(),[](S a,S b){return a.g>b.g;});
  for(int k=0;k<12;k++){
   S s=candidates[k];
   for(int z=0;z<90;z++){
    S n=s;float scale=z<40?1:.35;
    n.x+=normal()*3*scale;n.y+=normal()*3*scale;n.a+=normal()*.16*scale;n.len=max(1.f,min(250.f,n.len+normal()*8*scale));n.w=max(minw,min(maxw,n.w+normal()*2*scale));
    // Endpoints remain on the sheet, so each sweep is a single contact.
    float hx=abs(cos(n.a)*n.len/2),hy=abs(sin(n.a)*n.len/2);
    if(n.x-hx<2||n.x+hx>253||n.y-hy<2||n.y+hy>253)continue;
    evaluate(n);if(n.g>s.g)s=n;
   }
   if(s.g>best.g)best=s;
  }
  evaluate(best,true);
  out<<best.x<<" "<<best.y<<" "<<best.a<<" "<<best.len<<" "<<best.w<<" "<<best.c<<" "<<best.g<<endl;
  if(iter%20==0){double e=0;for(int k=0;k<N*N*3;k++)e+=pow(T[k]-C[k],2);fprintf(stderr,"%d rmse %.3f gain %.0f\n",iter,sqrt(e/(N*N*3)),best.g);}
 }
 f=fopen((string(argv[2])+".rgb").c_str(),"wb");fwrite(C,4,N*N*3,f);fclose(f);
}
